sql.where:
AND u.status != 2
/*DATA_SCOPE*/

    AND (
        u.username LIKE CONCAT('%', #{request.keyword}, '%')
        OR u.name LIKE CONCAT('%', #{request.keyword}, '%')
        OR u.phone LIKE CONCAT('%', #{request.keyword}, '%')
    )


    AND u.status = #{request.status}


    AND EXISTS (
        SELECT 1
        FROM sys_user_role ur_filter
        WHERE ur_filter.user_id = u.id
          AND ur_filter.role_id = #{request.roleId}
    )


    AND u.campus_id = #{request.campusId}

mapper.select:
SELECT COUNT(1)
FROM sys_internal_user u

    AND u.id = #{userId}
    AND u.status != 2
    /*DATA_SCOPE*/

mapper.update:
UPDATE sys_internal_user
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{userId}
  AND status != 2

UPDATE sys_internal_user
SET password = #{password},
    must_change_password = #{mustChangePassword},
    updated_at = #{updatedAt}
WHERE id = #{userId}
  AND status != 2

mapper.select:
SELECT COUNT(1)
FROM sys_user_role ur
         INNER JOIN sys_role r ON r.id = ur.role_id
WHERE ur.user_id = #{userId}
  AND r.code = #{roleCode}
  AND r.status = 1
